def get_task_for_structure(structure_name: str, modality: str) -> str:
    """Return the correct TotalSegmentator task for a given structure and modality."""
    if modality == "MR":
        # Check specific MR map first, then fallback to base
        if structure_name in TASK_MAP_MR:
            return TASK_MAP_MR[structure_name]
        return "total_mr"
    else:
        # CT
        if structure_name in TASK_MAP_CT:
            return TASK_MAP_CT[structure_name]
        return "total"

def group_structures_by_task(structure_names: list[str], modality: str) -> dict[str, list[str]]:
    groups = {}
    for s in structure_names:
        t = get_task_for_structure(s, modality)
        if t not in groups:
            groups[t] = []
        groups[t].append(s)
    return groups
